import{_ as p,r as n,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Page Finder Field - October CMS - 3.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"Page Finder"},"headers":[{"level":2,"title":"Linking to Pages","slug":"linking-to-pages","link":"#linking-to-pages","children":[]},{"level":2,"title":"Creating New Page Types","slug":"creating-new-page-types","link":"#creating-new-page-types","children":[{"level":3,"title":"Registering New Page Types","slug":"registering-new-page-types","link":"#registering-new-page-types","children":[]},{"level":3,"title":"Returning Information About a Page Type","slug":"returning-information-about-a-page-type","link":"#returning-information-about-a-page-type","children":[{"level":4,"title":"References","slug":"references","link":"#references","children":[]},{"level":4,"title":"CMS Pages","slug":"cms-pages","link":"#cms-pages","children":[]}]},{"level":3,"title":"Resolving Page Links","slug":"resolving-page-links","link":"#resolving-page-links","children":[]},{"level":3,"title":"Resolving Nested Page Links","slug":"resolving-nested-page-links","link":"#resolving-nested-page-links","children":[]},{"level":3,"title":"Resolving Other Site Links","slug":"resolving-other-site-links","link":"#resolving-other-site-links","children":[]},{"level":3,"title":"Usage Example","slug":"usage-example","link":"#usage-example","children":[]}]}],"relativePath":"3.x/element/form/widget-pagefinder.md","filePath":"3.x/element/form/widget-pagefinder.md"}'),r={name:"3.x/element/form/widget-pagefinder.md"};function u(k,s,g,d,h,m){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[a(t),s[0]||(s[0]=l("h1",null,"Page Finder Field",-1)),a(e),s[1]||(s[1]=i(`<p><code>pagefinder</code> - renders a field for selecting a page link. Expanding the field displays the picker to locate a page. The resulting selection is a string that contains the type and reference.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">featured_page</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Featured Page
    <span class="token key atrule">type</span><span class="token punctuation">:</span> pagefinder
</code></pre></div><p>The selected value is stored using the following format.</p><div class="language- extra-class"><pre class="language-text"><code>october://&lt;TYPE&gt;@link/&lt;REFERENCE&gt;?&lt;PARAM&gt;=&lt;VALUE&gt;
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>specifies a default string value, optional.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>singleMode</strong></td><td>only allows items to be selected that resolve to a single URL. Default: <code>false</code></td></tr></tbody></table></div><div class="custom-block tip"><p>Resolve the <code>pagefinder</code> value in lists using the <a href="./../lists/column-linkage.html">linkage column type</a>.</p></div><h2 id="linking-to-pages"><a href="#linking-to-pages" class="header-anchor">#</a> Linking to Pages</h2><p>Use the <a href="./../../markup/filter/link.html"><code>|link</code> Twig filter</a> to convert the page finder value to a URL.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> featured_page<span class="token operator">|</span>link <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Use the <a href="./../../markup/tag/content.html"><code>|content</code> Twig filter</a> to process HTML markup and replace all links within the content.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> blog_html<span class="token operator">|</span>content <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="creating-new-page-types"><a href="#creating-new-page-types" class="header-anchor">#</a> Creating New Page Types</h2><p>Plugins can extend the page finder with new page types using the various events. The most common place to subscribe to an event is the <code>boot</code> method of the plugin registration file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.listTypes&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.getTypeInfo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.resolveItem&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">,</span> <span class="token variable">$item</span><span class="token punctuation">,</span> <span class="token variable">$url</span><span class="token punctuation">,</span> <span class="token variable">$theme</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="registering-new-page-types"><a href="#registering-new-page-types" class="header-anchor">#</a> Registering New Page Types</h3><p>The <code>cms.pageLookup.listTypes</code> event handler returns a list of pages types supported by the plugin. The handler should return an associative array with the type codes in indexes and type names in values. It&#39;s highly recommended to use the plugin name in the type codes, to avoid conflicts with other page type providers. For example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.listTypes&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;blog-post&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog Post&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>For pages types that support nested subitems, such as linking to all blog posts, the type name value should be an array where the last item is set to <code>true</code>. This will exclude it from scenarios where only one link can be selected. The following marks the <strong>blog-posts</strong> type with nesting support.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.listTypes&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;blog-posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;All Blog Posts&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="returning-information-about-a-page-type"><a href="#returning-information-about-a-page-type" class="header-anchor">#</a> Returning Information About a Page Type</h3><p>The <code>cms.pageLookup.getTypeInfo</code> event handler returns detailed information about the supported page types. The handler gets a single parameter - the page type code (one of the codes you registered with the <code>cms.pageLookup.listTypes</code> handler). The handler code must check whether the requested item type code belongs to the plugin. The handler should return an associative array in the following format.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.getTypeInfo&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$type</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;blog-post&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;references&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token number">11</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;News&#39;</span><span class="token punctuation">,</span>
                <span class="token number">12</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Tutorials&#39;</span><span class="token punctuation">,</span>
                <span class="token number">13</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Philosophy&#39;</span><span class="token punctuation">,</span>
            <span class="token punctuation">]</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;cmsPages&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">withComponent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blogPosts&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="references"><a href="#references" class="header-anchor">#</a> References</h4><p>The <code>references</code> element is a list objects the page could refer to. For example, the <strong>Blog Category</strong> page type returns a list of the blog categories. Some object supports nesting, for example, complete page listings. Other objects don&#39;t support nesting, for example, blog categories. The format of the <code>references</code> value depends on whether the references have subitems or not. The format for references without subitems is the following.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;references&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;item-key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Item title&#39;</span>
<span class="token punctuation">]</span>
</code></pre></div><p>The format for references with subitems is the following.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;references&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;item-key&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Item title&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;items&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span>
</code></pre></div><p>The following iterator could be used to generate references where a model has children.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$iterator</span> <span class="token operator">=</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$records</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token variable">$iterator</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$result</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$records</span> <span class="token keyword">as</span> <span class="token variable">$record</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">children</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$result</span><span class="token punctuation">[</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token punctuation">{</span>
            <span class="token variable">$result</span><span class="token punctuation">[</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;items&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$iterator</span><span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">children</span><span class="token punctuation">)</span>
            <span class="token punctuation">]</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">return</span> <span class="token variable">$result</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;references&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$iterator</span><span class="token punctuation">(</span><span class="token variable">$records</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="cms-pages"><a href="#cms-pages" class="header-anchor">#</a> CMS Pages</h4><p>The <code>cmsPages</code> is a list of CMS pages that can display objects supported by the page type. For example, for the <strong>Blog Category</strong> item type the page list contains pages that host the <code>blogPosts</code> component. That component can display a blog category contents. The <code>cmsPages</code> element should be an array of the <code>Cms\\Classes\\Page</code> objects.</p><p>The following <code>withComponent</code> method will find all pages that use the <code>blogPosts</code> component, for the active theme.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;cmsPages&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">withComponent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blogPosts&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use <code>whereComponent</code> to find all pages using the <code>section</code> component where the property <code>handle</code> is set to <strong>Your\\Handle</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;cmsPages&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">whereComponent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;section&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;handle&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Your\\Handle&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Use <code>inTheme</code> to find pages in another theme by passing the theme code.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;cmsPages&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Page</span><span class="token operator">::</span><span class="token function">inTheme</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;demo&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withComponent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;blogPosts&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="resolving-page-links"><a href="#resolving-page-links" class="header-anchor">#</a> Resolving Page Links</h3><p>When the page finder generates links, every item should <strong>resolved</strong> by the plugin that supplies the item type. The process of resolving involves generating the real item URL, determining whether the item is active, and generating the subitems (if required).</p><p>The <code>cms.pageLookup.resolveItem</code> event handler resolves page information and returns the actual item URL, title, an indicator whether the item is currently active, and subitems, if any. The event handler takes four arguments:</p><ul><li><code>$type</code> - the item type name. Plugins must only handle item types they provide and ignore other types.</li><li><code>$item</code> - the item object (<code>Cms\\Models\\PageLookupItem</code>). The item object represents the item configuration provided by the user. The object has the following properties: <code>title</code>, <code>type</code>, <code>reference</code>, <code>cmsPage</code>.</li><li><code>$url</code> - specifies the current absolute URL, in lower case. Always use the <code>Url::to()</code> helper to generate item links and compare them with the current URL.</li><li><code>$theme</code> - the current theme object (<code>Cms\\Classes\\Theme</code>).</li></ul><p>The event handler should check for a matched <code>type</code> and return an array.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.resolveItem&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">,</span> <span class="token variable">$item</span><span class="token punctuation">,</span> <span class="token variable">$url</span><span class="token punctuation">,</span> <span class="token variable">$theme</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;blog-post&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">type</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;all-blog-posts&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>url</code> and <code>isActive</code> elements are required for items that point to a specific page.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Some Category&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;https://example.tld/blog/category/some-category&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;isActive&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="resolving-nested-page-links"><a href="#resolving-nested-page-links" class="header-anchor">#</a> Resolving Nested Page Links</h3><p>It is also possible for a resolved page link to return multiple items. For example, an <strong>All Pages</strong> item type wouldn&#39;t have a specific page to point to since it can have multiple links.</p><p>In these cases, the resolver will request subitems when the <code>$item</code> argument has a <code>nesting</code> property set to true.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.resolveItem&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">,</span> <span class="token variable">$item</span><span class="token punctuation">,</span> <span class="token variable">$url</span><span class="token punctuation">,</span> <span class="token variable">$theme</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Resolve item</span>
    <span class="token variable">$result</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token comment">// Subitems requested</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">nesting</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$result</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;items&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token variable">$result</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The items should be listed in the <code>items</code> element. The <code>items</code> element should only be provided for items marked as nested.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;https://example.tld/blog/category/another-category&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;isActive&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;items&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Another category&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;https://example.tld/blog/category/another-category&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;isActive&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;News&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;https://example.tld/blog/category/news&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;isActive&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">false</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="resolving-other-site-links"><a href="#resolving-other-site-links" class="header-anchor">#</a> Resolving Other Site Links</h3><p>It is possible for a resolved page link to return other sites that contain this page link. This is where the <code>$item</code> argument may contain a <code>sites</code> property that is set to true. The <code>Site</code> and <code>Cms</code> facades are helpful here, see the example below.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.resolveItem&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">,</span> <span class="token variable">$item</span><span class="token punctuation">,</span> <span class="token variable">$url</span><span class="token punctuation">,</span> <span class="token variable">$theme</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Resolve item</span>
    <span class="token variable">$result</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token variable">$page</span> <span class="token operator">=</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Cms<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Page</span><span class="token operator">::</span><span class="token function">loadCached</span><span class="token punctuation">(</span><span class="token variable">$theme</span><span class="token punctuation">,</span> <span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">reference</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Sites requested</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">sites</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$sites</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">hasMultiSite</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token class-name static-context">Site</span><span class="token operator">::</span><span class="token function">listEnabled</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">as</span> <span class="token variable">$site</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token variable">$url</span> <span class="token operator">=</span> <span class="token class-name static-context">Cms</span><span class="token operator">::</span><span class="token function">siteUrl</span><span class="token punctuation">(</span><span class="token variable">$page</span><span class="token punctuation">,</span> <span class="token variable">$site</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">slug</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;fullslug&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">fullslug</span>
                <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

                <span class="token variable">$sites</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$url</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$site</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;code&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$site</span><span class="token operator">-&gt;</span><span class="token property">code</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;locale&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$site</span><span class="token operator">-&gt;</span><span class="token property">hard_locale</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
        <span class="token punctuation">}</span>
        <span class="token variable">$result</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;sites&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$sites</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token variable">$result</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The resulting item should contain a <code>sites</code> array with a site definition object, each with a set <code>url</code> on the object.</p><h3 id="usage-example"><a href="#usage-example" class="header-anchor">#</a> Usage Example</h3><p>The following is a basic example of resolving a page URL by looking up a model and page URL using the <code>Cms\\Classes\\Controller</code> class and <code>pageUrl</code> method. It also processes child items recursively using the <code>children</code> relationship on the model, when requested using <code>$item-&gt;nesting</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cms.pageLookup.resolveItem&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$type</span><span class="token punctuation">,</span> <span class="token variable">$item</span><span class="token punctuation">,</span> <span class="token variable">$url</span><span class="token punctuation">,</span> <span class="token variable">$theme</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$type</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;my-model&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$model</span> <span class="token operator">=</span> <span class="token class-name static-context">MyModel</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">reference</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$controller</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Controller</span><span class="token punctuation">(</span><span class="token variable">$theme</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$pageUrl</span> <span class="token operator">=</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">pageUrl</span><span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">cmsPage</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">slug</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$result</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$pageUrl</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;isActive&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$pageUrl</span> <span class="token operator">==</span> <span class="token variable">$url</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;mtime&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">updated_at</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">nesting</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$result</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$iterator</span> <span class="token operator">=</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$children</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token variable">$iterator</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span><span class="token variable">$item</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span><span class="token variable">$theme</span><span class="token punctuation">,</span> <span class="token variable">$url</span><span class="token punctuation">,</span> <span class="token variable">$controller</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$branch</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

        <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$children</span> <span class="token keyword">as</span> <span class="token variable">$child</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$childUrl</span> <span class="token operator">=</span> <span class="token variable">$controller</span><span class="token operator">-&gt;</span><span class="token function">pageUrl</span><span class="token punctuation">(</span><span class="token variable">$item</span><span class="token operator">-&gt;</span><span class="token property">cmsPage</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">id</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;slug&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">slug</span>
            <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

            <span class="token variable">$childItem</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$childUrl</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;isActive&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$childUrl</span> <span class="token operator">==</span> <span class="token variable">$url</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$child</span><span class="token operator">-&gt;</span><span class="token property">title</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;mtime&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$child</span><span class="token operator">-&gt;</span><span class="token property">updated_at</span><span class="token punctuation">,</span>
            <span class="token punctuation">]</span><span class="token punctuation">;</span>

            <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$child</span><span class="token operator">-&gt;</span><span class="token property">children</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token variable">$childItem</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;items&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$iterator</span><span class="token punctuation">(</span><span class="token variable">$child</span><span class="token operator">-&gt;</span><span class="token property">children</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>

            <span class="token variable">$branch</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$childItem</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>

        <span class="token keyword">return</span> <span class="token variable">$branch</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">;</span>

    <span class="token variable">$result</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;items&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$iterator</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">children</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$result</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>As the resolving process occurs every time the frontend page is rendered, it is a good idea to cache all the information required for resolving items, if possible.</p></div>`,60))])}const y=p(r,[["render",u]]);export{b as __pageData,y as default};
